 async Task<object> Cover(string address){Uri uri;if(!Uri.TryCreate(address,UriKind.Absolute,out uri)||uri.Scheme!="https"||!(uri.Host.EndsWith(".googleusercontent.com")||uri.Host.EndsWith(".ggpht.com")||uri.Host=="i.ytimg.com"))return new{data=""};string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(address))).Replace("-","");string path=Path.Combine(Cache,hash+".cover");byte[] bytes=null;if(cacheMB>0&&File.Exists(path)){bytes=File.ReadAllBytes(path);File.SetLastWriteTimeUtc(path,DateTime.UtcNow);}else using(var response=await http.GetAsync(uri,HttpCompletionOption.ResponseHeadersRead)){if(!response.IsSuccessStatusCode||response.Content.Headers.ContentLength>1024*1024)return new{data=""};string type=response.Content.Headers.ContentType==null?"":response.Content.Headers.ContentType.MediaType;if(!new[]{"image/jpeg","image/png","image/webp"}.Contains(type))return new{data=""};using(var stream=await response.Content.ReadAsStreamAsync())using(var memory=new MemoryStream()){byte[] block=new byte[8192];int count;while((count=await stream.ReadAsync(block,0,block.Length))>0){if(memory.Length+count>1024*1024)return new{data=""};memory.Write(block,0,count);}bytes=memory.ToArray();}if(cacheMB>0){await cacheLock.WaitAsync();try{File.WriteAllBytes(path,bytes);}finally{cacheLock.Release();}await TrimCache();}}return new{data="data:image/jpeg;base64,"+Convert.ToBase64String(bytes)};}
