class DiscordPresence:IDisposable{
 NamedPipeClientStream pipe;string client;readonly SemaphoreSlim gate=new SemaphoreSlim(1,1),writeGate=new SemaphoreSlim(1,1);readonly Dictionary<string,TaskCompletionSource<string>> replies=new Dictionary<string,TaskCompletionSource<string>>();readonly JavaScriptSerializer json=new JavaScriptSerializer();CancellationTokenSource stop;
