 public static object Artwork(Dictionary<string,object> r){string value=r.ContainsKey("artwork")?Convert.ToString(r["artwork"]):"";Uri uri;if(value.Length>2048||!Uri.TryCreate(value,UriKind.Absolute,out uri)||uri.Scheme!="https"||!String.IsNullOrEmpty(uri.UserInfo)||!(uri.Host.EndsWith(".googleusercontent.com",StringComparison.OrdinalIgnoreCase)||uri.Host.EndsWith(".ggpht.com",StringComparison.OrdinalIgnoreCase)||uri.Host.Equals("i.ytimg.com",StringComparison.OrdinalIgnoreCase)))return null;string album=r.ContainsKey("album")?Convert.ToString(r["album"]):"";if(String.IsNullOrWhiteSpace(album))album=r.ContainsKey("title")?Convert.ToString(r["title"]):"Yuri Music";return new{large_image=uri.AbsoluteUri,large_text=album.Length>128?album.Substring(0,128):album};}
 public async Task<string> Update(Dictionary<string,object> r){await gate.WaitAsync();try{bool enabled=r.ContainsKey("enabled")&&Convert.ToBoolean(r["enabled"]);string id=r.ContainsKey("clientId")?Convert.ToString(r["clientId"]):"";if(!enabled){Dispose();return "Discord desativado.";}if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"^\d{17,22}$")){Dispose();return "Preencha o Application ID público do seu aplicativo Discord.";}if(pipe==null||!pipe.IsConnected||client!=id){Dispose();for(int i=0;i<10;i++){var next=new NamedPipeClientStream(".","discord-ipc-"+i,PipeDirection.InOut,PipeOptions.Asynchronous);try{await next.ConnectAsync(80);pipe=next;break;}catch{next.Dispose();}}if(pipe==null)return "Abra o Discord para PC para mostrar sua música.";client=id;await Send(0,new{v=1,client_id=id});var ready=Frame();if(await Task.WhenAny(ready,Task.Delay(2000))!=ready)throw new IOException();var handshake=await ready;if(!handshake.Contains("READY"))throw new IOException();stop=new CancellationTokenSource();var ignored=Drain(stop.Token);}
 string title=Convert.ToString(r["title"]),artist=Convert.ToString(r["artist"]);bool paused=Convert.ToBoolean(r["paused"]);object activity=null;if(!String.IsNullOrWhiteSpace(title)&&!paused){double position=Convert.ToDouble(r["position"]),duration=Convert.ToDouble(r["duration"]);long start=DateTimeOffset.UtcNow.ToUnixTimeSeconds()-(long)Math.Max(0,position);activity=new{type=2,details=title.Length>128?title.Substring(0,128):title,state=artist.Length>128?artist.Substring(0,128):artist,assets=Artwork(r),timestamps=new{start=start,end=start+(long)Math.Max(0,duration)}};}string nonce=Guid.NewGuid().ToString();var reply=new TaskCompletionSource<string>();lock(replies)replies[nonce]=reply;await Send(1,new{cmd="SET_ACTIVITY",args=new{pid=Process.GetCurrentProcess().Id,activity=activity},nonce=nonce});if(await Task.WhenAny(reply.Task,Task.Delay(2500))!=reply.Task){lock(replies)replies.Remove(nonce);return "Discord conectado, aguardando confirmação da presença.";}return (await reply.Task).Contains("\"ERROR\"")?"O Discord recusou a atividade. Confira seu Application ID.":"Presença confirmada pelo Discord.";
 }catch{Dispose();return "Não foi possível publicar a presença. Confira o Application ID e o Discord aberto.";}finally{gate.Release();}}
